SELECT AVG(sat) AS average_satisfaction 
FROM registration 
WHERE grade = 'B';

SELECT movie_title, release_date
FROM movies_total_gross
WHERE MPAA_rating = 'PG-13' AND genre = 'Romantic Comedy';

SELECT r.Forks, r.Url
FROM Repo r
WHERE r.Forks = (SELECT MAX(Forks) FROM Repo);

SELECT nameGiven, firstNHL, firstWHA
FROM Master
WHERE firstNHL IS NOT NULL AND firstWHA IS NOT NULL;

SELECT MIN(a.age) AS age FROM gender_age_train a
JOIN gender_age g ON a.device_id = g.device_id
WHERE g.gender = 'F';

SELECT AVG(longest_absense_from_school.month)
FROM longest_absense_from_school
JOIN disabled ON longest_absense_from_school.name = disabled.name;

SELECT COUNT(*) 
FROM Person p
WHERE p.birth_country = 'USA';

SELECT (ListPrice - StandardCost) * 10 AS Profit 
FROM Product 
WHERE Weight = (SELECT MIN(Weight) FROM Product);

SELECT AVG(CASE WHEN rating_score = 1 THEN 1.0 ELSE 0.0 END) * 100.0
FROM ratings
WHERE movie_id = (SELECT movie_id FROM movies WHERE movie_title = 'When Will I Be Loved');

SELECT Regions.Region 
FROM Regions 
WHERE EXISTS (SELECT 1 FROM "Store Locations" SL WHERE SL.StateCode = Regions.StateCode AND SL.Type = "Town");

SELECT yearsInProgram FROM person 
WHERE student = 1 
AND (SELECT COUNT(*) FROM advisedBy WHERE advisedBy.p_id = person.p_id) > 2;

SELECT description FROM FBI_Code
JOIN Crime ON Crime.fbi_code_no = FBI_Code.fbi_code_no
WHERE crime_against = 'Society';

SELECT COUNT(*) FROM Business 
WHERE business_id IN (
    SELECT business_id 
    FROM Business_Categories 
    WHERE category_id = (
        SELECT category_id 
        FROM Categories 
        WHERE category_name = 'Banks & Credit Unions'
    )
);

SELECT DISTINCT "Discount Applied"
FROM "Sales Orders"
WHERE _CustomerID = (SELECT CustomerID FROM Customers WHERE "Customer Names" = 'Ole Group');

SELECT AVG(longest_absense_from_school.month) 
FROM longest_absense_from_school 
WHERE NOT EXISTS (
    SELECT 1 FROM unemployed 
    WHERE unemployed.name = longest_absense_from_school.name
);

SELECT COUNT(*) 
FROM Community_Area 
WHERE community_area_name = 'Lincoln Square';

SELECT age FROM (
    SELECT 2022 - SUBSTR(DOB, 1, 4) AS age FROM Player WHERE Player_Name = 'Ishan Kishan'
);

SELECT vendor_name FROM resources
WHERE item_name = 'Classroom Keepers Management Center'
GROUP BY vendor_name;

SELECT ml.language_id
FROM movie_languages ml
WHERE ml.movie_id = (SELECT movie_id FROM movie ORDER BY popularity DESC LIMIT 1);

SELECT COUNT(*) FROM payments 
JOIN customers ON payments.customerNumber = customers.customerNumber 
WHERE customers.customerName = 'Euro+ Shopping Channel' AND strftime('%Y', paymentDate) = '2004';

SELECT (SUM(CASE WHEN award = 'NBA Coach of the Year' THEN 1 ELSE 0 END) * 100.0) / COUNT(*) AS percentage
FROM awards_coaches
WHERE year = 1969;

SELECT COUNT(CASE WHEN payment_method = 'creditcard' THEN 1 END) * 100.0 / COUNT(*) AS percentage
FROM donations d
WHERE d.projectid IN (SELECT projectid FROM essays WHERE title = 'Bringing Drama to Life');

SELECT COUNT(*) 
FROM Match 
WHERE Match_Winner IN (SELECT Team_Id FROM Team WHERE Team_Name = 'Pune Warriors');

SELECT MAX("historical".max_supply) - "historical".total_supply AS num_burned
FROM "historical"
WHERE "historical".date = '2013-04-28' AND "historical".coin_id = (
    SELECT id FROM coins WHERE slug = 'bitcoin'
)
GROUP BY "historical".coin_id;

SELECT name FROM Person 
INNER JOIN Credit ON Person.person_id = Credit.person_id 
WHERE credited = 'true' AND role = 'Alex Brown';

SELECT COUNT(*) FROM Business 
WHERE business_id IN (
    SELECT business_id 
    FROM Business_Categories 
    WHERE category_id = (
        SELECT category_id 
        FROM Categories 
        WHERE category_name = 'Shopping'
    )
);

SELECT ProductName
FROM Products
WHERE EXISTS (SELECT 1 FROM Suppliers WHERE Products.SupplierID = Suppliers.SupplierID AND Suppliers.Country = 'Finland');

SELECT COUNT(*) AS total_count
FROM course
WHERE courseLevel = 'Level_500';

SELECT title
FROM movie
WHERE movie_id IN (SELECT movie_id FROM movie_company WHERE company_id = (SELECT company_id FROM production_company WHERE company_name = 'Lucasfilm'));

SELECT COUNT(*) AS total_players
FROM PlayerInfo AS p
WHERE p.overallby = 'Arizona Coyotes' AND p.height = (SELECT height_id FROM height_info WHERE height_in_cm = 195);

SELECT COUNT(*) AS shipment_count FROM shipment 
WHERE CAST(ship_date AS DATE) = 2017 
AND EXISTS (SELECT 1 FROM city WHERE city_id = shipment.city_id AND state = 'New Jersey');

SELECT market_cap
FROM historical
WHERE date = '2013-04-28' AND coin_id = (SELECT id FROM coins WHERE slug = 'bitcoin');

SELECT MIN(weight) FROM players p
INNER JOIN player_allstar pa ON p.playerID = pa.playerID
WHERE p.college = 'UCLA';

SELECT FirstName, MiddleInitial, LastName
FROM Customers
WHERE CustomerID IN (SELECT CustomerID FROM Sales WHERE SalesPersonID = 5);

SELECT COUNT(*) FROM Airlines a 
JOIN "Air Carriers" ac ON a.OP_CARRIER_AIRLINE_ID = ac.Code 
WHERE ac.Description LIKE '%Republic Airline%' AND a.DEP_DELAY > 30;

SELECT genre_name
FROM genre
WHERE genre_id IN (SELECT genre_id FROM movie_genres WHERE movie_id = (SELECT movie_id FROM movie WHERE title = 'Dancer in the Dark'));

SELECT (SUM(rating_score = 1) * 100.0) / (SELECT COUNT(*) FROM ratings JOIN movies ON ratings.movie_id = movies.movie_id WHERE movie_title = 'When Will I Be Loved') 
FROM ratings JOIN movies ON ratings.movie_id = movies.movie_id 
WHERE movie_title = 'When Will I Be Loved';

SELECT Player_Id FROM Player WHERE Player_Id IN (
    SELECT Orange_Cap FROM Season
    GROUP BY Orange_Cap
    HAVING COUNT(Season_Year) = 2
);

SELECT youtube FROM "social-media" sm JOIN current s ON sm.bioguide = s.bioguide_id WHERE s.official_full_name = 'Chris Van Hollen' AND EXISTS (
    SELECT 1 FROM "current-terms" ct 
    WHERE ct.bioguide = s.bioguide_id
);

SELECT Regions.Region 
FROM Regions 
WHERE Regions.StateCode IN (SELECT StateCode FROM "Store Locations" WHERE Type = "Town");

SELECT COUNT(*) FROM events e1 WHERE EXISTS (
  SELECT 1 FROM events e2 
  WHERE e1.event_id = e2.event_id AND e1.device_id = 3915082290673130000
) AND e1.device_id = 3915082290673130000;

SELECT yearsInProgram FROM person 
WHERE student = 1 
AND p_id IN (SELECT p_id FROM advisedBy GROUP BY p_id HAVING COUNT(p_id_dummy) > 2);

SELECT COUNT(*) 
FROM MenuItem 
WHERE dish_id = (SELECT id FROM Dish WHERE name = 'Chicken gumbo');

SELECT COUNT(*) FROM trains t 
WHERE t.direction = 'west' 
AND (SELECT COUNT(*) FROM cars c WHERE c.train_id = t.id AND c.roof = 'none') <= 1;

SELECT genre_name 
FROM genre 
WHERE id = (SELECT genre_id FROM game WHERE game_name = 'Resident Evil: Revelations');

SELECT COUNT(*) FROM Business
WHERE business_id IN (
    SELECT business_id
    FROM Business_Categories
    WHERE category_id IN (
        SELECT category_id
        FROM Categories
        WHERE category_name = 'Banks & Credit Unions'
    )
);

SELECT AVG(longest_absense_from_school.month) 
FROM longest_absense_from_school 
JOIN person ON longest_absense_from_school.name = person.name 
WHERE person.name NOT IN (
    SELECT name FROM unemployed
);

SELECT DISTINCT r.vendor_name 
FROM resources r 
WHERE r.vendor_name IN (SELECT vendor_name FROM resources WHERE item_name = 'Classroom Keepers Management Center');

SELECT ingredient.name FROM Ingredient
INNER JOIN Quantity ON Ingredient.ingredient_id = Quantity.ingredient_id
WHERE Quantity.recipe_id = 1397 AND Quantity.optional = 'TRUE';

SELECT Name 
FROM PaperAuthor 
WHERE Affiliation = 'National Taiwan University Department of Computer Science and Information Engineering Taiwan';

SELECT COUNT(CASE WHEN payment_method = 'creditcard' THEN 1 END) * 100.0 / COUNT(*) AS percentage
FROM donations d
WHERE d.projectid = (SELECT projectid FROM essays WHERE title = 'Bringing Drama to Life');

SELECT (
    SELECT COUNT(*) 
    FROM BusinessEntityAddress 
    WHERE AddressTypeID = 2
) AS home_address_count, (
    SELECT COUNT(*) 
    FROM BusinessEntityAddress 
    WHERE AddressTypeID = 5
) AS shipping_address_count;

SELECT COUNT(*) FROM customer
WHERE c_acctbal < 0 AND c_nationkey IN (
    SELECT n_nationkey FROM nation
    WHERE n_regionkey IN (
        SELECT r_regionkey FROM region
        WHERE r_name = 'ASIA'
    )
);

SELECT COUNT(*) FROM incidents
WHERE case_number IN (
    SELECT case_number FROM subjects
    WHERE gender = 'F' AND subject_statuses = 'Deceased'
);

SELECT COUNT(*) FROM employee 
WHERE gender = 'M' 
AND locationID IN (SELECT locationID FROM location WHERE address = '450 Peachtree Rd');

SELECT title
FROM Episode
WHERE episode_id IN (SELECT episode_id FROM Keyword WHERE keyword = 'laundering money');

SELECT ProductName
FROM Products
WHERE SupplierID IN (SELECT SupplierID FROM Suppliers WHERE Country = 'Finland');

SELECT e.air_date
FROM Episode e
WHERE e.votes = (SELECT MAX(votes) FROM Episode);

SELECT COUNT(*) 
FROM customer
WHERE customer_id IN (SELECT customer_address.customer_id FROM customer_address WHERE address_id IN (SELECT address_id FROM address WHERE country_id = (SELECT country_id FROM country WHERE country_name = 'Australia')));

SELECT COUNT(*) FROM cust_order
WHERE customer_id = (SELECT customer_id FROM customer WHERE first_name = 'Antonia' AND last_name = 'Poltun')
AND order_id IN (SELECT order_id FROM order_history WHERE status_id = (SELECT status_id FROM order_status WHERE status_value = 'Returned'));

SELECT COUNT(*) FROM book
JOIN book_author ON book.book_id = book_author.book_id
WHERE book_author.author_id IN (
    SELECT author_id FROM author WHERE author_name = 'Orson Scott Card'
);

SELECT COUNT(*) AS shipment_count FROM shipment 
WHERE CAST(ship_date AS DATE) = 2017 
AND (SELECT state FROM city WHERE city_id = shipment.city_id) = 'New Jersey';

SELECT ROUND(COUNT(Repo.Id), 2) / (SELECT COUNT(*) FROM Repo) * 100 AS percentage 
FROM Repo 
WHERE Stars > 2000;

SELECT COUNT(*) AS count
FROM Airlines
WHERE OP_CARRIER_AIRLINE_ID = (
    SELECT Code FROM "Air Carriers" WHERE Description = 'American Airlines Inc.: AA'
)
AND DEST = 'JFK';

SELECT f_name, l_name, capability, gpa FROM student s
JOIN RA r ON s.student_id = r.student_id
JOIN prof p ON p.prof_id = r.prof_id
WHERE p.prof_id IN (
    SELECT prof_id FROM prof WHERE first_name = 'Merwyn' AND last_name = 'Conkay'
);

SELECT COUNT(*)
FROM shipment
WHERE truck_id IN (SELECT truck_id FROM truck WHERE model_year = (SELECT MIN(model_year) FROM truck));

SELECT COUNT(DISTINCT user_id) FROM ratings 
WHERE movie_id = (SELECT movie_id FROM movies WHERE movie_title = 'A Way of Life') 
AND rating_score = 5;

SELECT state FROM Business WHERE business_id IN (
    SELECT business_id 
    FROM Business_Hours 
    JOIN Days ON Business_Hours.day_id = Days.day_id
    WHERE opening_time = '1AM'
);

SELECT Repo.Url FROM Repo 
JOIN Solution ON Repo.Id = Solution.RepoId 
WHERE Repo.Stars = (SELECT MAX(Stars) FROM Repo);

SELECT CASE WHEN EXISTS (SELECT 1 FROM male WHERE name = 'student995') THEN 'male' ELSE 'female' END AS gender, school 
FROM enrolled 
WHERE name = 'student995';
